"use client";

import { useEffect, useRef, useState } from "react";

const SYNC_OFFSET_MS = 0; // positive = glow runs ahead
export { SYNC_OFFSET_MS };

// YouTube IFrame API global
declare global {
  interface Window {
    onYouTubeIframeAPIReady?: () => void;
  }
}

type PlayerState = "UNSTARTED" | "PLAYING" | "PAUSED" | "BUFFERING" | "ENDED";

interface YTPlayer {
  playVideo(): void;
  pauseVideo(): void;
  stopVideo(): void;
  getCurrentTime(): number;
  getPlaybackRate(): number;
  getPlayerState(): number;
  destroy(): void;
}

interface YouTubeClockState {
  time: number; // seconds, 2 decimals
  state: PlayerState;
  rate: number; // playback rate (1.0 normal)
  player: YTPlayer | null;
}

export function useYouTubeClock(iframeRef: React.RefObject<HTMLIFrameElement | null>): YouTubeClockState {
  const [state, setState] = useState<YouTubeClockState>({ time: 0, state: "UNSTARTED", rate: 1.0, player: null });
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const lastPolledTimeRef = useRef<number>(0);
  const lastPolledTimestampRef = useRef<number>(0);

  useEffect(() => {
    let mounted = true;

    const initClock = () => {
      if (!iframeRef.current) return;

      const loadIFrameAPI = new Promise<void>((resolve) => {
        if ((window as any).YT) {
          resolve();
        } else {
          const tag = document.createElement("script");
          tag.src = "https://www.youtube.com/iframe_api";
          const firstScriptTag = document.getElementsByTagName("script")[0];
          firstScriptTag.parentNode?.insertBefore(tag, firstScriptTag);
          window.onYouTubeIframeAPIReady = () => resolve();
        }
      });

      loadIFrameAPI.then(() => {
        if (!mounted) return;

        const YT = (window as any).YT;
        if (!YT) return;

        const player = new YT.Player(iframeRef.current, {
          events: {
            onReady: (event: { target: YTPlayer }) => {
              if (!mounted) return;
              const ytPlayer = event.target;

              const tick = () => {
                if (!mounted) return;

                const now = performance.now();
                const currentTime = ytPlayer.getCurrentTime();
                const playbackRate = ytPlayer.getPlaybackRate();
                const playerStateNum = ytPlayer.getPlayerState();

                let targetTime = lastPolledTimeRef.current;
                if (lastPolledTimestampRef.current > 0) {
                  const elapsedSincePoll = (now - lastPolledTimestampRef.current) / 1000;
                  const baseProgress = elapsedSincePoll * playbackRate;
                  const smoothedProgress = baseProgress * 0.5 + lastPolledTimeRef.current * 0.5;
                  targetTime += smoothedProgress;
                }

                // Snap if user seeked > 0.6s away
                if (Math.abs(currentTime - targetTime) > 0.6) {
                  targetTime = currentTime;
                }

                lastPolledTimeRef.current = currentTime;
                lastPolledTimestampRef.current = now;

                // Map YT state to ours
                let newState: PlayerState = "UNSTARTED";
                switch (playerStateNum) {
                  case 0: newState = "ENDED"; break;
                  case 1: newState = "PLAYING"; break;
                  case 2: newState = "PAUSED"; break;
                  case 3: newState = "BUFFERING"; break;
                  default: newState = "UNSTARTED";
                }

                // Extrapolate while playing
                let newTime = targetTime;
                if (newState === "PLAYING") {
                  const rate = playbackRate;
                  newTime = targetTime + (now - lastPolledTimestampRef.current) / 1000 * rate;
                }

                // Apply sync offset
                const adjustedTime = newTime + SYNC_OFFSET_MS / 1000;

                // Normalize negative times
                const finalTime = adjustedTime < 0 ? 0 : adjustedTime;

                if (mounted) {
                  setState(prev => ({
                    ...prev,
                    time: Math.round(finalTime * 100) / 100,
                    state: newState,
                    rate: playbackRate,
                    player: prev.player
                  }));
                }
              };

              intervalRef.current = setInterval(tick, 250);

              // Set initial time
              const initialTime = ytPlayer.getCurrentTime();
              setState(prev => ({
                ...prev,
                time: Math.round(initialTime * 100) / 100,
                state: "UNSTARTED",
                rate: 1.0,
                player: ytPlayer
              }));
            },
            onStateChange: () => {
              // State will be updated on next tick
            }
          }
        });
      });
    };

    initClock();

    return () => {
      mounted = false;
      if (intervalRef.current) clearInterval(intervalRef.current);
      intervalRef.current = null;
      if (state.player) {
        try { state.player.destroy(); } catch {}
      }
    };
  }, [iframeRef]);

  return state;
}