"use client";

import { useEffect, useRef, useState } from "react";
import type { Project } from "../content";

type GlowFrame = { r: number; g: number; b: number };
type GlowTrack = { frames: GlowFrame[]; fps: number; w: number; h: number; duration: number };
type GlowState = "idle" | "loading" | "loaded" | "error";
type ClockState = "UNSTARTED" | "PLAYING" | "PAUSED" | "BUFFERING" | "ENDED" | "FALLBACK";

const DEBUG_KEY = "ambientDebug";

// Read debug flag once on mount, never change it
function getDebugMode(): boolean {
  if (typeof window === "undefined") return false;
  const params = new URLSearchParams(window.location.search);
  return params.get(DEBUG_KEY) === "1";
}

interface VideoClockState {
  time: number;
  state: ClockState;
  rate: number;
  player: any | null;
}

const BREAKPOINTS = {
  desktop: { nearBlur: 56, farBlur: 140 },
  tablet: { nearBlur: 44, farBlur: 120 },
  mobile: { nearBlur: 36, farBlur: 0 },
};

function getBreakpoints() {
  const w = typeof window !== "undefined" ? window.innerWidth : 1024;
  if (w >= 1024) return BREAKPOINTS.desktop;
  if (w >= 640) return BREAKPOINTS.tablet;
  return BREAKPOINTS.mobile;
}

// Draw a 16×9 frame to an offscreen canvas, returns ImageData
function frameToImageData(frame: GlowFrame, frames: GlowFrame[]): ImageData {
  const w = 16, h = 9;
  const rgba = new Uint8ClampedArray(w * h * 4);
  for (let i = 0; i < w * h; i++) {
    rgba[i * 4] = frame.r;
    rgba[i * 4 + 1] = frame.g;
    rgba[i * 4 + 2] = frame.b;
    rgba[i * 4 + 3] = 255;
  }
  return new ImageData(rgba, w, h);
}

export function AmbientGlow({
  project,
  videoClock,
  visible,
  reducedMotion,
}: {
  project: Project;
  videoClock: VideoClockState;
  visible: boolean;
  reducedMotion: boolean;
}) {
  const debugMode = useRef(getDebugMode());
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const farCanvasRef = useRef<HTMLCanvasElement>(null);

  const [track, setTrack] = useState<GlowTrack | null>(null);
  const [state, setState] = useState<GlowState>("idle");
  const [lastError, setLastError] = useState<string>("");
  const [debugInfo, setDebugInfo] = useState<Record<string, string | number | boolean>>({});

  const rafRef = useRef<number | null>(null);
  const smoothFrameRef = useRef<GlowFrame>({ r: 128, g: 128, b: 128 });
  const pauseFadeStartRef = useRef<number | null>(null);
  const clockAttachTimeRef = useRef<number>(0);
  const fallbackStartTimeRef = useRef<number>(0);
  const trackLoadedTimeRef = useRef<number>(0);

  // ── Hooks first, always in the same order ────────────────────────────────

  // Fetch track
  useEffect(() => {
    if (!visible || !project.youtubeId) return;

    const controller = new AbortController();
    const log = (...args: any[]) => {
      if (debugMode.current) console.log("[AmbientGlow]", ...args);
    };

    log("fetch started", project.youtubeId);
    setState("loading");

    const loadTrack = async () => {
      try {
        const binUrl = `/ambient/${project.youtubeId}.bin`;
        const manifestUrl = `/ambient/manifest.json`;

        log("fetching", binUrl, manifestUrl);

        const [trackRes, manifestRes] = await Promise.all([
          fetch(binUrl, { signal: controller.signal, cache: "force-cache" }),
          fetch(manifestUrl, { signal: controller.signal, cache: "force-cache" }),
        ]);

        log("fetch responses:", trackRes.status, manifestRes.status);

        if (!trackRes.ok) throw new Error(`Track HTTP ${trackRes.status}`);
        if (!manifestRes.ok) throw new Error(`Manifest HTTP ${manifestRes.status}`);

        const arrayBuffer = await trackRes.arrayBuffer();
        const bytes = new Uint8Array(arrayBuffer);
        log("track bytes:", bytes.length);

        if (bytes.length % 432 !== 0) throw new Error(`Invalid track size: ${bytes.length}`);

        const frameCount = bytes.length / 432;
        const manifestData = await manifestRes.json() as Record<string, any>;
        const entry = manifestData[project.youtubeId];

        if (!entry) throw new Error(`Missing manifest entry for ${project.youtubeId}`);

        log("manifest entry:", entry);

        const frames: GlowFrame[] = [];
        for (let i = 0; i < frameCount; i++) {
          const base = i * 432;
          frames.push({ r: bytes[base], g: bytes[base + 1], b: bytes[base + 2] });
        }

        setTrack({ frames, fps: entry.fps, w: entry.w, h: entry.h, duration: entry.duration });
        trackLoadedTimeRef.current = performance.now();
        setState("loaded");
        log("track loaded:", frames.length, "frames");
      } catch (e) {
        const msg = String(e);
        log("track error:", msg);
        setLastError(msg);
        setState("error");
      }
    };

    loadTrack();
    return () => controller.abort();
  }, [project.youtubeId, visible]);

  // Draw to canvas on each frame update
  useEffect(() => {
    if (!track || !visible) {
      if (rafRef.current) {
        cancelAnimationFrame(rafRef.current);
        rafRef.current = null;
      }
      return;
    }

    const draw = () => {
      if (!visible) {
        rafRef.current = null;
        return;
      }

      const targetTime = videoClock.time;
      const targetFrame = targetTime * track.fps;
      const frameIndex = Math.min(Math.floor(targetFrame), track.frames.length - 1);

      // Interpolate
      let interpFrame: GlowFrame;
      if (frameIndex < targetFrame && frameIndex < track.frames.length - 1) {
        const t = targetFrame - frameIndex;
        const f1 = track.frames[frameIndex];
        const f2 = track.frames[frameIndex + 1];
        interpFrame = {
          r: Math.round(f1.r * (1 - t) + f2.r * t),
          g: Math.round(f1.g * (1 - t) + f2.g * t),
          b: Math.round(f1.b * (1 - t) + f2.b * t),
        };
      } else {
        interpFrame = track.frames[frameIndex];
      }

      // Low-pass filter
      const current = smoothFrameRef.current;
      const alpha = 1 - Math.exp(-16 / 1000);
      smoothFrameRef.current = {
        r: Math.round(current.r + (interpFrame.r - current.r) * alpha),
        g: Math.round(current.g + (interpFrame.g - current.g) * alpha),
        b: Math.round(current.b + (interpFrame.b - current.b) * alpha),
      };

      // Draw to near canvas
      if (canvasRef.current) {
        const ctx = canvasRef.current.getContext("2d");
        if (ctx) {
          const imageData = frameToImageData(smoothFrameRef.current, track.frames);
          ctx.putImageData(imageData, 0, 0);
        }
      }

      // Draw to far canvas
      if (farCanvasRef.current) {
        const ctx = farCanvasRef.current.getContext("2d");
        if (ctx) {
          const imageData = frameToImageData(smoothFrameRef.current, track.frames);
          ctx.putImageData(imageData, 0, 0);
        }
      }

      rafRef.current = requestAnimationFrame(draw);
    };

    // Draw first frame immediately
    smoothFrameRef.current = track.frames[0];
    if (canvasRef.current) {
      const ctx = canvasRef.current.getContext("2d");
      if (ctx) {
        const imageData = frameToImageData(smoothFrameRef.current, track.frames);
        ctx.putImageData(imageData, 0, 0);
      }
    }
    if (farCanvasRef.current) {
      const ctx = farCanvasRef.current.getContext("2d");
      if (ctx) {
        const imageData = frameToImageData(smoothFrameRef.current, track.frames);
        ctx.putImageData(imageData, 0, 0);
      }
    }

    rafRef.current = requestAnimationFrame(draw);

    return () => {
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [track, visible, videoClock.time, videoClock.state]);

  // Update debug HUD
  useEffect(() => {
    if (!debugMode.current) return;

    const interval = setInterval(() => {
      setDebugInfo({
        track: !!track,
        bytes: track ? track.frames.length * 3 : 0,
        frames: track?.frames.length ?? 0,
        clockState: videoClock.state,
        clockTime: videoClock.time,
        frameIndex: track ? Math.min(Math.floor(videoClock.time * track.fps), track.frames.length - 1) : 0,
        visible,
        nearBlur: getBreakpoints().nearBlur,
        farBlur: getBreakpoints().farBlur,
        error: lastError,
      });
    }, 200);

    return () => clearInterval(interval);
  }, [track, videoClock, visible, lastError]);

  // ── Renders after all hooks ──────────────────────────────────────────────

  // No project youtube id → render nothing (safe, no hooks affected)
  if (!project.youtubeId) return null;

  // Error fallback: always render a gray glow regardless of debug mode
  if (state === "error" || !track) {
    return (
      <div
        style={{
          position: "absolute", inset: 0, zIndex: 1, pointerEvents: "none",
          opacity: visible ? 0.3 : 0, transition: "opacity 600ms ease",
        }}
        data-ambient="true"
        data-ambient-state={state === "error" ? "error-fallback" : "loading"}
        aria-hidden="true"
      >
        <canvas
          width={1}
          height={1}
          style={{
            position: "absolute", inset: 0,
            background: "rgb(100, 100, 100)",
            filter: `blur(${getBreakpoints().nearBlur}px)`,
          }}
        />
        {debugMode.current && (
          <div style={debugHUDStyle}>
            <div><b>Ambient Glow Debug</b></div>
            <div>Track: NO</div>
            {lastError && <div style={{ color: "red" }}>Error: {lastError}</div>}
            {state === "loading" && <div>Loading...</div>}
          </div>
        )}
      </div>
    );
  }

  const breakpoints = getBreakpoints();
  const isEnded = videoClock.state === "ENDED";
  const nearOpacity = visible ? 0.9 : 0;
  const farOpacity = visible ? (isEnded ? 0.38 : 0.55) : 0;

  return (
    <>
      <div
        style={{
          position: "absolute",
          left: 0, right: 0, top: 0, bottom: 0,
          zIndex: 1,
          pointerEvents: "none",
          opacity: visible ? 1 : 0,
          transition: "opacity 600ms ease",
          contain: "paint",
        }}
        data-ambient="true"
        data-ambient-state={videoClock.state}
        data-ambient-time={videoClock.time.toFixed(2)}
        aria-hidden="true"
        role="presentation"
      >
        {/* Near glow canvas */}
        <canvas
          ref={canvasRef}
          width={16}
          height={9}
          style={{
            position: "absolute",
            left: "50%",
            top: "50%",
            transform: "translate(-50%, -50%)",
            width: "32vw",
            height: "32vh",
            filter: `blur(${breakpoints.nearBlur}px) saturate(1.7) brightness(1.12)`,
            maskImage: "radial-gradient(ellipse at center, #000 52%, transparent 100%)",
            WebkitMaskImage: "radial-gradient(ellipse at center, #000 52%, transparent 100%)",
            willChange: "contents",
            imageRendering: "auto",
            opacity: nearOpacity,
            ...(debugMode.current ? { outline: "2px solid red" } : {}),
          }}
        />

        {/* Far glow canvas (desktop/tablet only) */}
        {breakpoints.farBlur > 0 && (
          <canvas
            ref={farCanvasRef}
            width={16}
            height={9}
            style={{
              position: "absolute",
              left: "50%",
              top: "50%",
              transform: "translate(-50%, -50%)",
              width: "80vw",
              height: "60vh",
              filter: `blur(${breakpoints.farBlur}px) saturate(1.8) brightness(1.1)`,
              maskImage: "radial-gradient(ellipse at center, #000 52%, transparent 100%)",
              WebkitMaskImage: "radial-gradient(ellipse at center, #000 52%, transparent 100%)",
              willChange: "contents",
              imageRendering: "auto",
              opacity: farOpacity,
              ...(debugMode.current ? { outline: "2px dashed cyan" } : {}),
            }}
          />
        )}

        {/* Debug HUD */}
        {debugMode.current && (
          <div style={debugHUDStyle}>
            <div><b>Ambient Glow Debug</b></div>
            <div>Track: YES ({debugInfo.frames}f, {debugInfo.bytes}B)</div>
            <div>Clock: {debugInfo.clockState} @ {(Number(debugInfo.clockTime) || 0).toFixed(2)}s</div>
            <div>Frame: {debugInfo.frameIndex}</div>
            <div>Near: blur={debugInfo.nearBlur}px, opacity={nearOpacity}</div>
            {debugInfo.farBlur !== undefined && (
              <div>Far: blur={debugInfo.farBlur}px, opacity={farOpacity}</div>
            )}
            <div>Visible: {String(visible)}</div>
            {debugInfo.error && <div style={{ color: "red" }}>Error: {debugInfo.error}</div>}
            <div>Wrapper z-index: 1</div>
          </div>
        )}
      </div>
    </>
  );
}

const debugHUDStyle: React.CSSProperties = {
  position: "fixed",
  bottom: 16,
  left: 16,
  zIndex: 99999,
  background: "rgba(0,0,0,.75)",
  color: "white",
  fontFamily: "monospace",
  fontSize: 11,
  padding: "8px 12px",
  borderRadius: 4,
  pointerEvents: "none",
  lineHeight: 1.5,
};
